fun buildGraph(n: Int, edges: Array<IntArray>, directed: Boolean = false): List<List<Int>> {
    val graph = List(n) { mutableListOf<Int>() }
    for ((u, v) in edges) {
        graph[u].add(v)
        if (!directed) graph[v].add(u)             // undirected: add both directions
    }
    return graph
}

// Weighted version: neighbor and weight
fun buildWeightedGraph(n: Int, edges: Array<IntArray>): List<List<Pair<Int, Int>>> {
    val graph = List(n) { mutableListOf<Pair<Int, Int>>() }
    for ((u, v, w) in edges) {
        graph[u].add(Pair(v, w))
        graph[v].add(Pair(u, w))
    }
    return graph
}
// Build: O(V + E)   Space: O(V + E)

fun bfs(graph: List<List<Int>>, start: Int): List<Int> {
    val order = mutableListOf<Int>()
    val visited = BooleanArray(graph.size)
    val queue = ArrayDeque<Int>()
    visited[start] = true                          // mark when ADDING to the queue
    queue.addLast(start)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        order.add(node)
        for (next in graph[node]) {
            if (!visited[next]) {
                visited[next] = true
                queue.addLast(next)
            }
        }
    }
    return order
}
// Time: O(V + E)   Space: O(V)

fun shortestDistances(graph: List<List<Int>>, start: Int): IntArray {
    val dist = IntArray(graph.size) { -1 }         // -1 means unreachable
    val queue = ArrayDeque<Int>()
    dist[start] = 0
    queue.addLast(start)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        for (next in graph[node]) {
            if (dist[next] == -1) {
                dist[next] = dist[node] + 1
                queue.addLast(next)
            }
        }
    }
    return dist
}
// dist doubles as the visited array
// Time: O(V + E)   Space: O(V)

fun dfs(graph: List<List<Int>>, start: Int): List<Int> {
    val order = mutableListOf<Int>()
    val visited = BooleanArray(graph.size)

    fun visit(node: Int) {
        visited[node] = true
        order.add(node)
        for (next in graph[node]) {
            if (!visited[next]) visit(next)
        }
    }

    visit(start)
    return order
}
// Time: O(V + E)   Space: O(V) for visited and recursion

fun dfsIterative(graph: List<List<Int>>, start: Int): List<Int> {
    val order = mutableListOf<Int>()
    val visited = BooleanArray(graph.size)
    val stack = ArrayDeque<Int>()
    stack.addLast(start)
    while (stack.isNotEmpty()) {
        val node = stack.removeLast()
        if (visited[node]) continue                // mark when POPPING for iterative DFS
        visited[node] = true
        order.add(node)
        for (next in graph[node].asReversed()) {   // reversed to match recursive order
            if (!visited[next]) stack.addLast(next)
        }
    }
    return order
}
// Time: O(V + E)   Space: O(V)

// Each cell is a node; its neighbors are up, down, left and right.
val DIRS = arrayOf(
    intArrayOf(1, 0), intArrayOf(-1, 0),
    intArrayOf(0, 1), intArrayOf(0, -1)
)

fun inBounds(r: Int, c: Int, rows: Int, cols: Int): Boolean =
    r in 0 until rows && c in 0 until cols

// Grid BFS shortest path (0 = open, 1 = wall)
fun shortestPathGrid(grid: Array<IntArray>, start: IntArray, end: IntArray): Int {
    val rows = grid.size
    val cols = grid[0].size
    val visited = Array(rows) { BooleanArray(cols) }
    val queue = ArrayDeque<IntArray>()
    queue.addLast(intArrayOf(start[0], start[1], 0))   // row, col, distance
    visited[start[0]][start[1]] = true
    while (queue.isNotEmpty()) {
        val (r, c, d) = queue.removeFirst()
        if (r == end[0] && c == end[1]) return d
        for ((dr, dc) in DIRS) {
            val nr = r + dr
            val nc = c + dc
            if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == 0 && !visited[nr][nc]) {
                visited[nr][nc] = true
                queue.addLast(intArrayOf(nr, nc, d + 1))
            }
        }
    }
    return -1
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun countComponents(n: Int, edges: Array<IntArray>): Int {
    val graph = buildGraph(n, edges)
    val visited = BooleanArray(n)
    var count = 0

    fun dfs(node: Int) {
        visited[node] = true
        for (next in graph[node]) {
            if (!visited[next]) dfs(next)
        }
    }

    for (i in 0 until n) {
        if (!visited[i]) {                         // a new, unvisited component
            count++
            dfs(i)
        }
    }
    return count
}
// Time: O(V + E)   Space: O(V)

// Start BFS from several sources at once. Every source is at distance 0.
fun multiSourceBfs(rows: Int, cols: Int, sources: List<IntArray>): Array<IntArray> {
    val dist = Array(rows) { IntArray(cols) { -1 } }
    val queue = ArrayDeque<IntArray>()
    for (s in sources) {
        dist[s[0]][s[1]] = 0
        queue.addLast(s)
    }
    while (queue.isNotEmpty()) {
        val (r, c) = queue.removeFirst()
        for ((dr, dc) in DIRS) {
            val nr = r + dr
            val nc = c + dc
            if (inBounds(nr, nc, rows, cols) && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1
                queue.addLast(intArrayOf(nr, nc))
            }
        }
    }
    return dist
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun hasCycleUndirected(n: Int, edges: Array<IntArray>): Boolean {
    val graph = buildGraph(n, edges)
    val visited = BooleanArray(n)

    fun dfs(node: Int, parent: Int): Boolean {
        visited[node] = true
        for (next in graph[node]) {
            if (!visited[next]) {
                if (dfs(next, node)) return true
            } else if (next != parent) {
                return true                        // reached a visited node that is not the parent
            }
        }
        return false
    }

    for (i in 0 until n) {
        if (!visited[i] && dfs(i, -1)) return true
    }
    return false
}
// Time: O(V + E)   Space: O(V)
// For a directed graph use three states (see Course Schedule below)

fun numIslands(grid: Array<CharArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    var count = 0

    fun dfs(r: Int, c: Int) {
        if (r !in 0 until rows || c !in 0 until cols || grid[r][c] != '1') return
        grid[r][c] = '0'                           // sink the land so it is not counted again
        dfs(r + 1, c); dfs(r - 1, c)
        dfs(r, c + 1); dfs(r, c - 1)
    }

    for (r in 0 until rows) {
        for (c in 0 until cols) {
            if (grid[r][c] == '1') {
                count++
                dfs(r, c)
            }
        }
    }
    return count
}
// Time: O(rows * cols)   Space: O(rows * cols) worst-case recursion

fun maxAreaOfIsland(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size

    fun dfs(r: Int, c: Int): Int {
        if (r !in 0 until rows || c !in 0 until cols || grid[r][c] != 1) return 0
        grid[r][c] = 0
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)
    }

    var best = 0
    for (r in 0 until rows) for (c in 0 until cols) {
        if (grid[r][c] == 1) best = maxOf(best, dfs(r, c))
    }
    return best
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun floodFill(image: Array<IntArray>, sr: Int, sc: Int, color: Int): Array<IntArray> {
    val original = image[sr][sc]
    if (original == color) return image            // nothing to do, avoids an infinite loop
    val rows = image.size
    val cols = image[0].size

    fun dfs(r: Int, c: Int) {
        if (r !in 0 until rows || c !in 0 until cols || image[r][c] != original) return
        image[r][c] = color
        dfs(r + 1, c); dfs(r - 1, c)
        dfs(r, c + 1); dfs(r, c - 1)
    }

    dfs(sr, sc)
    return image
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun orangesRotting(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    val queue = ArrayDeque<IntArray>()
    var fresh = 0
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            when (grid[r][c]) {
                2 -> queue.addLast(intArrayOf(r, c))
                1 -> fresh++
            }
        }
    }

    var minutes = 0
    while (queue.isNotEmpty() && fresh > 0) {
        repeat(queue.size) {                       // one minute = one BFS level
            val (r, c) = queue.removeFirst()
            for ((dr, dc) in DIRS) {
                val nr = r + dr
                val nc = c + dc
                if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == 1) {
                    grid[nr][nc] = 2
                    fresh--
                    queue.addLast(intArrayOf(nr, nc))
                }
            }
        }
        minutes++
    }
    return if (fresh == 0) minutes else -1
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun shortestPathBinaryMatrix(grid: Array<IntArray>): Int {
    val n = grid.size
    if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return -1
    val queue = ArrayDeque<IntArray>()
    queue.addLast(intArrayOf(0, 0, 1))             // row, col, path length
    grid[0][0] = 1                                 // mark visited
    while (queue.isNotEmpty()) {
        val (r, c, d) = queue.removeFirst()
        if (r == n - 1 && c == n - 1) return d
        for (dr in -1..1) {
            for (dc in -1..1) {
                if (dr == 0 && dc == 0) continue
                val nr = r + dr
                val nc = c + dc
                if (nr in 0 until n && nc in 0 until n && grid[nr][nc] == 0) {
                    grid[nr][nc] = 1
                    queue.addLast(intArrayOf(nr, nc, d + 1))
                }
            }
        }
    }
    return -1
}
// Time: O(n²)   Space: O(n²)

fun updateMatrix(mat: Array<IntArray>): Array<IntArray> {
    val rows = mat.size
    val cols = mat[0].size
    val dist = Array(rows) { IntArray(cols) { -1 } }
    val queue = ArrayDeque<IntArray>()
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            if (mat[r][c] == 0) {
                dist[r][c] = 0
                queue.addLast(intArrayOf(r, c))     // every 0 is a source
            }
        }
    }
    while (queue.isNotEmpty()) {
        val (r, c) = queue.removeFirst()
        for ((dr, dc) in DIRS) {
            val nr = r + dr
            val nc = c + dc
            if (inBounds(nr, nc, rows, cols) && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1
                queue.addLast(intArrayOf(nr, nc))
            }
        }
    }
    return dist
}
// Time: O(rows * cols)   Space: O(rows * cols)
// One BFS from all zeros beats a BFS from every 1

fun pacificAtlantic(heights: Array<IntArray>): List<List<Int>> {
    val rows = heights.size
    val cols = heights[0].size
    val pacific = Array(rows) { BooleanArray(cols) }
    val atlantic = Array(rows) { BooleanArray(cols) }

    // flow uphill from the ocean: move to cells that are at least as high
    fun dfs(r: Int, c: Int, visited: Array<BooleanArray>) {
        visited[r][c] = true
        for ((dr, dc) in DIRS) {
            val nr = r + dr
            val nc = c + dc
            if (inBounds(nr, nc, rows, cols) && !visited[nr][nc] &&
                heights[nr][nc] >= heights[r][c]) {
                dfs(nr, nc, visited)
            }
        }
    }

    for (r in 0 until rows) {
        dfs(r, 0, pacific)
        dfs(r, cols - 1, atlantic)
    }
    for (c in 0 until cols) {
        dfs(0, c, pacific)
        dfs(rows - 1, c, atlantic)
    }

    val result = mutableListOf<List<Int>>()
    for (r in 0 until rows) for (c in 0 until cols) {
        if (pacific[r][c] && atlantic[r][c]) result.add(listOf(r, c))
    }
    return result
}
// Time: O(rows * cols)   Space: O(rows * cols)
// Searching from the border inward avoids testing every cell separately

class GNode(var `val`: Int) {
    var neighbors: MutableList<GNode> = mutableListOf()
}

fun cloneGraph(node: GNode?): GNode? {
    if (node == null) return null
    val copies = HashMap<GNode, GNode>()            // original -> copy, also acts as visited

    fun dfs(cur: GNode): GNode {
        copies[cur]?.let { return it }              // already cloned
        val copy = GNode(cur.`val`)
        copies[cur] = copy                          // register BEFORE visiting neighbors
        for (nb in cur.neighbors) copy.neighbors.add(dfs(nb))
        return copy
    }

    return dfs(node)
}
// Time: O(V + E)   Space: O(V)

fun findCircleNum(isConnected: Array<IntArray>): Int {
    val n = isConnected.size
    val visited = BooleanArray(n)
    var provinces = 0

    fun dfs(i: Int) {
        visited[i] = true
        for (j in 0 until n) {
            if (isConnected[i][j] == 1 && !visited[j]) dfs(j)
        }
    }

    for (i in 0 until n) {
        if (!visited[i]) {
            provinces++
            dfs(i)
        }
    }
    return provinces
}
// Time: O(V²)   Space: O(V)

fun validPath(n: Int, edges: Array<IntArray>, source: Int, destination: Int): Boolean {
    val graph = buildGraph(n, edges)
    val visited = BooleanArray(n)
    val queue = ArrayDeque<Int>()
    queue.addLast(source)
    visited[source] = true
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        if (node == destination) return true
        for (next in graph[node]) {
            if (!visited[next]) {
                visited[next] = true
                queue.addLast(next)
            }
        }
    }
    return false
}
// Time: O(V + E)   Space: O(V + E)

fun allPathsSourceTarget(graph: Array<IntArray>): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()
    val target = graph.size - 1
    path.add(0)

    fun dfs(node: Int) {
        if (node == target) {
            result.add(ArrayList(path))             // copy the current path
            return
        }
        for (next in graph[node]) {
            path.add(next)
            dfs(next)
            path.removeAt(path.lastIndex)           // backtrack
        }
    }

    dfs(0)
    return result
}
// Time: O(2^V * V) worst case   Space: O(V)
// No visited set needed in a DAG, because there are no cycles

fun canFinish(numCourses: Int, prerequisites: Array<IntArray>): Boolean {
    val graph = List(numCourses) { mutableListOf<Int>() }
    for ((course, pre) in prerequisites) graph[pre].add(course)

    val state = IntArray(numCourses)               // 0 = unvisited, 1 = on current path, 2 = done

    fun hasCycle(node: Int): Boolean {
        if (state[node] == 1) return true          // back edge: found a cycle
        if (state[node] == 2) return false
        state[node] = 1
        for (next in graph[node]) {
            if (hasCycle(next)) return true
        }
        state[node] = 2
        return false
    }

    for (i in 0 until numCourses) {
        if (hasCycle(i)) return false
    }
    return true
}
// Time: O(V + E)   Space: O(V + E)
// See Topological Sort for producing the actual order

fun isBipartite(graph: Array<IntArray>): Boolean {
    val color = IntArray(graph.size) { -1 }         // -1 = uncolored
    for (start in graph.indices) {
        if (color[start] != -1) continue
        color[start] = 0
        val queue = ArrayDeque<Int>()
        queue.addLast(start)
        while (queue.isNotEmpty()) {
            val node = queue.removeFirst()
            for (next in graph[node]) {
                if (color[next] == -1) {
                    color[next] = 1 - color[node]   // opposite color
                    queue.addLast(next)
                } else if (color[next] == color[node]) {
                    return false                    // two neighbors share a color
                }
            }
        }
    }
    return true
}
// Time: O(V + E)   Space: O(V)

fun ladderLength(beginWord: String, endWord: String, wordList: List<String>): Int {
    val words = wordList.toHashSet()
    if (endWord !in words) return 0
    val visited = HashSet<String>()
    val queue = ArrayDeque<Pair<String, Int>>()
    queue.addLast(Pair(beginWord, 1))
    visited.add(beginWord)
    while (queue.isNotEmpty()) {
        val (word, steps) = queue.removeFirst()
        if (word == endWord) return steps
        val chars = word.toCharArray()
        for (i in chars.indices) {
            val original = chars[i]
            for (c in 'a'..'z') {
                if (c == original) continue
                chars[i] = c
                val next = String(chars)
                if (next in words && visited.add(next)) {
                    queue.addLast(Pair(next, steps + 1))
                }
            }
            chars[i] = original                     // restore before changing the next position
        }
    }
    return 0
}
// Time: O(N * L * 26)   Space: O(N * L)

fun openLock(deadends: Array<String>, target: String): Int {
    val dead = deadends.toHashSet()
    if ("0000" in dead) return -1
    if (target == "0000") return 0
    val visited = hashSetOf("0000")
    val queue = ArrayDeque<String>()
    queue.addLast("0000")
    var steps = 0
    while (queue.isNotEmpty()) {
        steps++
        repeat(queue.size) {
            val cur = queue.removeFirst()
            for (i in 0 until 4) {
                for (delta in intArrayOf(1, 9)) {            // +1 or -1 modulo 10
                    val chars = cur.toCharArray()
                    chars[i] = '0' + (chars[i] - '0' + delta) % 10
                    val next = String(chars)
                    if (next in dead || !visited.add(next)) continue
                    if (next == target) return steps
                    queue.addLast(next)
                }
            }
        }
    }
    return -1
}
// Time: O(10^4 * 4 * 2)   Space: O(10^4)

fun validTree(n: Int, edges: Array<IntArray>): Boolean {
    if (edges.size != n - 1) return false           // a tree has exactly n - 1 edges
    val graph = buildGraph(n, edges)
    val visited = BooleanArray(n)
    val stack = ArrayDeque<Int>()
    stack.addLast(0)
    visited[0] = true
    var seen = 1
    while (stack.isNotEmpty()) {
        val node = stack.removeLast()
        for (next in graph[node]) {
            if (!visited[next]) {
                visited[next] = true
                seen++
                stack.addLast(next)
            }
        }
    }
    return seen == n                                // n - 1 edges and connected means no cycle
}
// Time: O(V + E)   Space: O(V + E)
